# Alle Zahlen von 1 bis 10 außer den Vielfachen von 3
for i in range(1, 11):
    if i % 3 == 0:
        continue
    print(i)
# Ausgabe: 1 2 4 5 7 8 10 (je in einer Zeile)

for i in range(1, 4):
    for j in range(1, 4):
        if j == 2:
            break      # beendet nur die innere Schleife
        print(i, j)
# 1 1
# 2 1
# 3 1

